\u003a\u0066\u005b\u0065\u0079\u007d\u003b\u0069\u0023\u0032\u002d\u003e\u005c\u006f\u006d\u003d\u006a\u007d\u0055\u004d\u0041\u0073\u0051\u004d\u004c\u0021\u0023\u004d\u0077\u0066\u002a\u0048\u0033\u006f\u002b\u0037\u0070\u0075\u005b\u003b\u0061\u0028\u0077\u007e\u004d\u005e\u0072\u0060\u0069\u0030\u002e\u0031\u005a\u004f\u0061\u0057\u0064\u002c\u0073\u005d\u0067\u006f\u003a\u0052\u005c\u0037\u004a\u0059\u003c\u0067\u006f\u005a\u0043\u0056\u0069\u0034\u0074\u0064\u0029\u003a\u0049\u003d\u007c\u0060\u0023\u0033\u0067\u004d\u002a\u003f\u006d\u0032\u0063\u005f\u0030\u0065\u006b\u0072\u002d\u002f\u0036\u007d\u0076\u002c\u006f\u0064\u004c\u0022\u002b\u004e\u0079\u0070\u006b\u004a\u0032\u004e\u0078\u0050\u006c\u007d\u0071\u0066\u003e\u0073\u0064\u0079\u005a\u006e\u0030\u0059\u0062\u0079\u007e\u0042\u0053\u0050\u0066\u002a\u006f\u005e\u0020\u0025\u004b\u003c\u0059\u006b\u0074\u0051\u002f\u002b\u0067\u0065\u0073\u004e\u005a\u0070\u0028\u005b\u0073\u0042\u0029\u002e\u0046\u005f\u0056\u0060\u0048\u004c\u0057\u0037\u0041\u002b\u003c\u0069\u002e\u0030\u0032\u0054\u0060\u0049\u002f\u002f\u0020\u0050\u0079\u007b\u0056\u0074\u0061\u0078\u0038\u0024\u007b\u003f\u0053\u0078\u0063\u0031\u0063\u002d\u002d\u0057\u0057\u006b\u004b\u003e\u0073\u006a\u003e\u004a\u0040\u0071\u0020\u007c\u006f\u0036\u0059\u0046\u0044\u0043\u007b\u007e\u0054\u006b\u0045\u006e\u0076\u0055\u0048\u0031\u007b\u005f\u0043\u0076\u0055\u0064\u0063\u005b\u0036\u0024\u004b\u0062\u007a\u002e\u0058\u0030\u002c\u0026\u0058\u0040\u0073\u0059\u0034\u0044\u0040\u0034\u006a\u0043\u007d\u0064\u0047\u003b\u0049\u0026\u0059\u005c\u002e\u003d\u0021\u0028\u0031\u0021\u004e\u0068\u002c\u0056\u006f\u006a\u0062\u0077\u005c\u002b\u0058\u0047\u005b\u0043\u0025\u006a\u0038\u0050\u0056\u0027\u0041\u006c\u0038\u0075\u002c\u007a\u0067\u0044\u0037\u0022\u0021\u0037\u0045\u0034\u0052\u0053\u0066\u0068\u0045\u005a\u0036\u004b\u005d\u003d\u0029\u0059\u006c\u0060\u0055\u0028\u006e\u0056\u002b\u0030\u002a\u007b\u0034\u007d\u0062\u0074\u0074\u0079\u0059\u0041\u002f\u0038\u0040\u0068\u0051\u0067\u0057\u0059\u0028\u005d\u0068\u0035\u0063\u0071\u0046\u0061\u0055\u0021\u0046\u0063\u0047\u002b\u0075\u0057\u0057\u0036\u0032\u0057\u0074\u0044\u0045\u0063\u0068\u0075\u005e\u007e\u002b\u0042\u0044\u006b\u0023\u0078\u0037\u0079\u0034\u0068\u0026\u006e\u002a\u002f\u0028\u005f\u004d\u0079\u0024\u0041\u0029\u0061\u0058\u0067\u006d\u0044\u0074\u0026\u003a\u005f\u0030\u0024\u0060\u0020\u004b\u003e\u0022\u006e\u0057\u0042\u0050\u0044\u0073\u007b\u0048\u0038\u0051\u0066\u006d\u003b\u0037\u006e\u007c\u003c\u0062\u0061\u0031\u0056\u0071\u0024\u0053\u005b\u005d\u002c\u002e\u003e\u0046\u0067\u0069\u0041\u003d\u003e\u0050\u003b\u003f\u0075\u002a\u006a\u0053\u0065\u002f\u0054\u0027\u0037\u007b\u0033\u0050\u0037\u006e\u005d\u003c\u0021\u0037\u003d\u0064\u0039\u0055\u0074\u006a\u0055\u006e\u0066\u0071\u0042\u006f\u0074\u0033\u0031\u0071\u002d\u0026\u0029\u0068\u0034\u005c\u004b\u0038\u002d\u003c\u005f\u0020\u0020\u004e\u007d\u0075\u003c\u0071\u004a\u005d\u0065\u0022\u0060\u0052\u005c\u0040\u003a\u0031\u005c\u006d\u004f\u0061\u002c\u0028\u006e\u0069\u0070\u0077\u005a\u004f\u0070\u004b\u0059\u0074\u006d\u0042\u005c\u0061\u0070\u005e\u0034\u0020\u0028\u006f\u0027\u003e\u005b\u0054\u0032\u0065\u003f\u004c\u0042\u0050\u0056\u0023\u0077\u0068\u0037\u0051\u003d\u006d\u0052\u007d\u007d\u0058\u0040\u007a\u0060\u0074\u004c\u003c\u0066\u0021\u0024\u0062\u0026\u004c\u0027\u0074\u0026\u0057\u0046\u0069\u0040\u002f\u005d\u005d\u0041\u0078\u0070\u006c\u003b\u0022\u0048\u002d\u0054\u004f\u0054\u007c\u0072\u006e\u0046\u0074\u0066\u0039\u0021\u0050\u007c\u0035\u002d\u002b\u0022\u0043\u0025\u005a\u004a\u0052\u0039\u0033\u005d\u0064\u0022\u0077\u0065\u005b\u0058\u0037\u0036\u0037\u003f\u0058\u0027\u003d\u0032\u003e\u006e\u0038\u0063\u003d\u007c\u0048\u002f\u0041\u0056\u002c\u003b\u002d\u0032\u0052\u003d\u002f\u002b\u0053\u0072\u006d\u0052\u007d\u0070\u006f\u0076\u003c\u0036\u006a\u005c\u0034\u006a\u0054\u0058\u0036\u0048\u0050\u0037\u0078\u004c\u002e\u0037\u004d\u0051\u0022\u003b\u005f\u0057\u0020\u0027\u002f\u0068\u0076\u0024\u006e\u0073\u002d\u0077\u0028\u0022\u0053\u005a\u0025\u0028\u002f\u0027\u0077\u0040\u0024\u007d\u002b\u006f\u0057\u0036\u0048\u0070\u0063\u0025\u005d\u0066\u004a\u0032\u003f\u0054\u007c\u0079\u006e\u0023\u005d\u006d\u0049\u0053\u0041\u0078\u005f\u0056\u002d\u006a\u0025\u003a\u0036\u003c\u006c\u0060\u004d\u0047\u0036\u004a\u002b\u007d\u002e\u0020\u0037\u0023\u0079\u004f\u0067\u004a\u007c\u0057\u0067\u007c\u0039\u0028\u003d\u0073\u0036\u002c\u0050\u0046\u0053\u0077\u003f\u0061\u0044\u0056\u006d\u0027\u0060\u0079\u0075\u0063\u0055\u0068\u0074\u003c\u006b\u0046\u0051\u004f\u004d\u0053\u004f\u0056\u0049\u0040\u0067\u0032\u0058\u0042\u0046\u003e\u0040\u007d\u002f\u0046\u006a\u0024\u0028\u0071\u0072\u0046\u0062\u0034\u0074\u0050\u0041\u003b\u003d\u006a\u0067\u0052\u005c\u0058\u002d\u0052\u0040\u0055\u005e\u004f\u007d\u0065\u0070\u006d\u004a\u003f\u006f\u0073\u0056\u007b\u003e\u0079\u0038\u0071\u0076\u004b\u007c\u004e\u007c\u0074\u0060\u0033\u006a\u0056\u004f\u004a\u0049\u003d\u003a\u007c\u002b\u0058\u0025\u004d\u0025\u003b\u0076\u007c\u005c\u002a\u004f\u0044\u004e\u007b\u003c\u0043\u0021\u0048\u0054\u0075\u003f\u0032\u0076\u0076\u0072\u0031\u0064\u0035\u0035\u005e\u0031\u003d\u003b\u004b\u006f\u0045\u0035\u004b\u002f\u004f\u0078\u0054\u0065\u0023\u0049\u0077\u0040\u003d\u0048\u0045\u005b\u0045\u003b\u0038\u0059\u0024\u0023\u0022\u0051\u0038\u0026\u002a\u004f\u003d\u0027\u0045\u003b\u003f\u0071\u0028\u0061\u0074\u0044\u0067\u0049\u0073\u0044\u004c\u0061\u0077\u007a\u005d\u002f\u0061\u0074\u0037\u0063\u003b\u0054\u0044\u0040\u0028\u0071\u0069\u005d\u006b\u0060\u0032\u007c\u003b\u006d\u005c\u0030\u0035\u0038\u003c\u006b\u0067\u0044\u005e\u0039\u0055\u003c\u0069\u0053\u007e\u007b\u005a\u0055\u005f\u0037\u004b\u005d\u0024\u0064\u0071\u007e\u003a\u0048\u0033\u0043\u003a\u0029\u0066\u0052\u0024\u0039\u002f\u006b\u003c\u007c\u007d\u0025\u0057\u003c\u0048\u005f\u0063\u0049\u0068\u0070\u007d\u0026\u005b\u0028\u003d\u007d\u0022\u002d\u002e\u0042\u0050\u007c\u005a\u0061\u0075\u002f\u0052\u0020\u005a\u0051\u003d\u0054\u0023\u006e\u0046\u004d\u0059\u0029\u0075\u0025\u003a\u004a\u007a\u0026\u0025\u0071\u0077\u0023\u005d\u005d\u0073\u0045\u006a\u003c\u0032\u0044\u004d\u003d\u0054\u0046\u003a\u003f\u004b\u0036\u003b\u002d\u006f\u006d\u005a\u006e\u0028\u0065\u0049\u007c\u003c\u0079\u0051\u0033\u005e\u0022\u002d\u006f\u0065\u0041\u0028\u0075\u002d\u0068\u0079\u0071\u0038\u0069\u003f\u0057\u006f\u0076\u0062\u002f\u0040\u0021\u0071\u0043\u0071\u0022\u0062\u0042\u007b\u0065\u0076\u0037\u002c\u0051\u005d\u0052\u0052\u005e\u0038\u006e\u0058\u0032\u005b\u0032\u0028\u0066\u005b\u0042\u004d\u0061\u0050\u0036\u003b\u007d\u002e\u002a\u0070\u0053\u003d\u0031\u002e\u005f\u003c\u006f\u0056\u0047\u0054\u0037\u003a\u005c\u0079\u006f\u0046\u003f\u0057\u005b\u0024\u0042\u006b\u0042\u004b\u0063\u0054\u0066\u006e\u004a\u0042\u0026\u0031\u0075\u003f\u003d\u002b\u0037\u006a\u002b\u006d\u0024\u0031\u0079\u0064\u007b\u0035\u003e\u003b\u0024\u003e\u003a\u004f\u0027\u006c\u002a\u0049\u0060\u0073\u0025\u0039\u0062\u007b\u0029\u0038\u003f\u006e\u003b\u0030\u0068\u0021\u0039\u007c\u0057\u006b\u007b\u0054\u0031\u0078\u0052\u003f\u003b\u0020\u007b\u0030\u0074\u002b\u007a\u0032\u0057\u0074\u0027\u0057\u0072\u0042\u0034\u0030\u0039\u007c\u0050\u002e\u0032\u004f\u0049\u002f\u007d\u0037\u0029\u0059\u0066\u0051\u0027\u0067\u0032\u0065\u0021\u0020\u0024\u0071\u007a\u003b\u0073\u007d\u0029\u0072\u0054\u0054\u0034\u007c\u0024\u0050\u0064\u0060\u0034\u0033\u0069\u0072\u003a\u002a\u0041\u0060\u002d\u0033\u0071\u003f\u0042\u0059\u0020\u0073\u007d\u0071\u0073\u007e\u0032\u002d\u0074\u004d\u005b\u0043\u0075\u004e\u006e\u0044\u005e\u005e\u0023\u0031\u007b\u004e\u0044\u0046\u007e\u0070\u0055\u0078\u0021\u006c\u0067\u0072\u007d\u0062\u002b\u0059\u0048\u005f\u0054\u0020\u0070\u0052\u0037\u005e\u002a\u006a\u006c\u0067\u0055\u0044\u007b\u0033\u0063\u0036\u0024\u0069\u0061\u0040\u004e\u004b\u007e\u004c\u0046\u0078\u0051\u0043\u0056\u004c\u002d\u0060\u0039\u0035\u0068\u0055\u004e\u006b\u0030\u0073\u0051\u005b\u0062\u0049\u003e\u0051\u0038\u0025\u0046\u002c\u0021\u004b\u0052\u0077\u0020\u0065\u0074\u0078\u0073\u006f\u0067\u007e\u0056\u0035\u0050\u0051\u004d\u005b\u0025\u0050\u0074\u0048\u004c\u0026\u0075\u0035\u0026\u0062\u0028\u0052\u0051\u002f\u0037\u006d\u0076\u004e\u004d\u0054\u0035\u004f\u005e\u0046\u0033\u0064\u0078\u0069\u0071\u0024\u0065\u006c\u0037\u0076\u005a\u0053\u006b\u0039\u0078\u0047\u0028\u0072\u004a\u002b\u0065\u0051\u005e\u0050\u0048\u0028\u0064\u0022\u007d\u005e\u003b\u005d\u005d\u006b\u007e\u0022\u002f\u006e\u003a\u0078\u003e\u0059\u003d\u0072\u002b\u0040\u0039\u0069\u0072\u0069\u0062\u0078\u0073\u0064\u0072\u002d\u004c\u004d\u005e\u0069\u0032\u0024\u003c\u0071\u002d\u0040\u005c\u0036\u0064\u0073\u0031\u0022\u006a\u0038\u006b\u0027\u0072\u0027\u0041\u0053\u0037\u005d\u003b\u006d\u0073\u003e\u0039\u0076\u0066\u0025\u003f\u002d\u002a\u0055\u0061\u006d\u004c\u006b\u0050\u0062\u0057\u0060\u0051\u004b\u0033\u0036\u0069\u0074\u007a\u0031\u003e\u0036\u0067\u0035\u005a\u0066\u006a\u002a\u0061\u004b\u0035\u0021\u007d\u0029\u005e\u0058\u005f\u0041\u0046\u007c\u0027\u0045\u003a\u0025\u004d\u0061\u002c\u0031\u0065\u0035\u003e\u0047\u0029\u0045\u002c\u005e\u0024\u0055\u006b\u004f\u0021\u005d\u0068\u0036\u005c\u0058\u004c\u005c\u0068\u0033\u0049\u0054\u005b\u0042\u0048\u006c\u0029\u0062\u0028\u0056\u0067\u003d\u004a\u004a\u0074\u0044\u0058\u0058\u007d\u005b\u0066\u006e\u0040\u005d\u0048\u0025\u0032\u0021\u0033\u002b\u0075\u007b\u0054\u002b\u004c\u0050\u0038\u0035\u0032\u0061\u0038\u0073\u0041\u004a\u0059\u0040\u0022\u0031\u0077\u0057\u0036\u0045\u002a\u002b\u0072\u0058\u0069\u007a\u0022\u002e\u0045\u0022\u005a\u0063\u0021\u003e\u0047\u0056\u006c\u003e\u002f\u005e\u0064\u0047\u006b\u005d\u002f\u003f\u007c\u003e\u0038\u0069\u0053\u006d\u005f\u005e\u006e\u0051\u0053\u004b\u0047\u0060\u0029\u0035\u0053\u0026\u0031\u0064\u0075\u0041\u004f\u006f\u0049\u0059\u0056\u0070\u006c\u006a\u0022\u0052\u0069\u0073\u0028\u003e\u0074\u0075\u0062\u005e\u004c\u005c\u006e\u0072\u007a\u0054\u002a\u0060\u005f\u005d\u005b\u004e\u0021\u0053\u003a\u0050\u0069\u0034\u004e\u006d\u0026\u002f\u0039\u0031\u005e\u006b\u0033\u006e\u0058\u007c\u0060\u003e\u005d\u0032\u0028\u0056\u003a\u007c\u0065\u0038\u003a\u007d\u0040\u007e\u0073\u003e\u004a\u005b\u006e\u007c\u0034\u0034\u007a\u0058\u0023\u003c\u004a\u0079\u005a\u0076\u003c\u002b\u004b\u0042\u002d\u0076\u0030\u005b\u0075\u0037\u0078\u0078\u0049\u0049\u0059\u006d\u0073\u0045\u0038\u0064\u002b\u004c\u0075\u0069\u0074\u004b\u002c\u0074\u0049\u0043\u0044\u004e\u005b\u0031\u0050\u0074\u006f\u0038\u0061\u0041\u004a\u0040\u004e\u002d\u0034\u004a\u007e\u0031\u0023\u0052\u003b\u0050\u0045\u002d\u006e\u0023\u003f\u0027\u006c\u005d\u002a\u0028\u0024\u004d\u0034\u0075\u007b\u0072\u0073\u0027\u0028\u007c\u002d\u0061\u0036\u0046\u007b\u0031\u0027\u0036\u0075\u0062\u006f\u007d\u005f\u0046\u003d\u0047\u0037\u0029\u0042\u005f\u0038\u006b\u002f\u0079\u0053\u0039\u0024\u007a\u0069\u0072\u0042\u0062\u0037\u0053\u003f\u0076\u0028\u0029\u005b\u0037\u005c\u007e\u0079\u0022\u005f\u003c\u0064\u006a\u0045\u006a\u004a\u003d\u002e\u0053\u0079\u004e\u0072\u004c\u0033\u0049\u0041\u0079\u0042\u005a\u0036\u006b\u0045\u0063\u002f\u0034\u0060\u006d\u006d\u0042\u005e\u0058\u0044\u0024\u0025\u0056\u0055\u006f\u0024\u0045\u0073\u0041\u0075\u0028\u005c\u0051\u0027\u0023\u0053\u0074\u003d\u0056\u006e\u0067\u0057\u0057\u005f\u0055\u002a\u003f\u007c\u005c\u0059\u0021\u002d\u0040\u003a\u0032\u004c\u0053\u007c\u0025\u0021\u003d\u0040\u007d\u007a\u0056\u0051\u0028\u0039\u005f\u003b\u0062\u003b\u0038\u002e\u0047\u0052\u0028\u0067\u0076\u0056\u006b\u004c\u007e\u0055\u0062\u006d\u0069\u0037\u003f\u005c\u0021\u0054\u004d\u0064\u007e\u0065\u005e\u007c\u0064\u0051\u004e\u005c\u003d\u0022\u003d\u0048\u0039\u004c\u0049\u0071\u0024\u0062\u0041\u0070\u0059\u0027\u004d\u006d\u004d\u0065\u0054\u0058\u0034\u0021\u007c\u0024\u0030\u0022\u0064\u0052\u004b\u005c\u0071\u006e\u0059